create type public.ad_space_status as enum ('available', 'reserved', 'active_campaign', 'inactive');
create type public.ad_space_type as enum ('wall', 'picture_frame', 'clothing_pocket', 'clothing_back', 'face_left', 'face_right', 'other');
create type public.ad_type as enum ('static_image_ad', 'video_product_placement', 'product_intro_video', 'sponsored_feature', 'product_test_video', 'custom');
create type public.listing_category as enum ('beauty_skincare', 'fashion_style', 'fitness_health', 'food_beverage', 'travel', 'technology_gadgets', 'gaming', 'lifestyle', 'home_decor', 'parenting_family', 'education_learning', 'arts_crafts', 'business_finance', 'automotive', 'sports', 'music_entertainment', 'pets_animals', 'photography', 'comedy_entertainment', 'other', 'any');
create type public.listing_order_status as enum ('pending_payment', 'paid_in_escrow', 'delivered', 'confirmed', 'released', 'expired_auto_confirmed', 'cancelled');
create type public.listing_status as enum ('draft', 'active', 'paused', 'pending_review', 'rejected', 'removed');
create type public.order_status as enum ('pending_payment', 'paid', 'in_progress', 'completed', 'cancelled', 'refunded', 'confirmed', 'rejected');
create type public.payment_channel as enum ('stripe', 'wechat_pay', 'alipay');
create type public.payout_status as enum ('pending', 'paid', 'failed');
create type public.pricing_unit as enum ('one_time', 'daily', 'weekly', 'monthly');
create type public.social_platform as enum ('douyin', 'xiaohongshu', 'weibo', 'wechat_channel', 'youtube', 'instagram', 'tiktok', 'bilibili', 'other');
create type public.user_role as enum ('seller', 'buyer', 'both');

alter table public.ad_spaces add constraint ad_spaces_pkey PRIMARY KEY (id);
alter table public.admins add constraint admins_pkey PRIMARY KEY (user_id);
alter table public.campaigns add constraint campaigns_pkey PRIMARY KEY (id);
alter table public.contact_messages add constraint contact_messages_pkey PRIMARY KEY (id);
alter table public.listing_messages add constraint listing_messages_pkey PRIMARY KEY (id);
alter table public.listing_order_proof_changes add constraint listing_order_proof_changes_pkey PRIMARY KEY (id);
alter table public.listing_orders add constraint listing_orders_pkey PRIMARY KEY (id);
alter table public.listing_orders add constraint listing_orders_booking_dates_check CHECK ((((start_date IS NULL) = (end_date IS NULL)) AND ((end_date IS NULL) OR (end_date >= start_date)) AND ((booking_units IS NULL) OR (booking_units > 0))));
alter table public.listing_orders add constraint listing_orders_payout_hold_check CHECK (((payout_hold IS NULL) OR (payout_hold = ANY (ARRAY['dispute'::text, 'refund'::text, 'seller_banned'::text]))));
alter table public.listings add constraint listings_pkey PRIMARY KEY (id);
alter table public.listings add constraint listings_booking_check CHECK ((((NOT booking_enabled) OR (pricing_unit <> 'one_time'::pricing_unit)) AND ((min_booking_days IS NULL) OR ((min_booking_days >= 1) AND (min_booking_days <= 90)))));
alter table public.orders add constraint orders_pkey PRIMARY KEY (id);
alter table public.payments add constraint payments_pkey PRIMARY KEY (id);
alter table public.payouts add constraint payouts_pkey PRIMARY KEY (id);
alter table public.profiles add constraint profiles_pkey PRIMARY KEY (id);
alter table public.profiles add constraint profiles_username_unique UNIQUE (username);
alter table public.profiles add constraint profiles_username_format CHECK (((username IS NULL) OR (username ~ '^[a-z0-9][a-z0-9-]{1,28}[a-z0-9]$'::text)));
alter table public.proof_uploads add constraint proof_uploads_pkey PRIMARY KEY (id);
alter table public.rate_limits add constraint rate_limits_pkey PRIMARY KEY (bucket, key_hash, window_start);
alter table public.seller_price_card_items add constraint seller_price_card_items_pkey PRIMARY KEY (id);
alter table public.seller_profiles add constraint seller_profiles_pkey PRIMARY KEY (user_id);
alter table public.seller_profiles add constraint seller_profiles_website_url_http CHECK (((website_url IS NULL) OR (website_url ~* '^https?://'::text))) NOT VALID;
alter table public.site_pages add constraint site_pages_pkey PRIMARY KEY (slug);
alter table public.site_pages add constraint site_pages_slug_check CHECK ((slug = ANY (ARRAY['terms'::text, 'privacy'::text])));
alter table public.social_accounts add constraint social_accounts_pkey PRIMARY KEY (id);
alter table public.social_accounts add constraint social_accounts_url_http CHECK (((url IS NULL) OR (url ~* '^https?://'::text))) NOT VALID;

alter table public.ad_spaces add constraint ad_spaces_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES profiles(id) ON DELETE CASCADE;
alter table public.admins add constraint admins_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id);
