alter table public.listing_orders add constraint listing_orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES profiles(id);
alter table public.listing_orders add constraint listing_orders_cancelled_by_fkey FOREIGN KEY (cancelled_by) REFERENCES profiles(id);
alter table public.listing_orders add constraint listing_orders_listing_id_fkey FOREIGN KEY (listing_id) REFERENCES listings(id);
alter table public.listing_orders add constraint listing_orders_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES profiles(id);
