create policy "Sellers can update own ad_spaces" on ad_spaces as permissive for update to public
  using ((auth.uid() = seller_id))
  with check ((auth.uid() = seller_id));

create policy "anyone can view ad_spaces" on ad_spaces as permissive for select to anon, authenticated
  using (true);

create policy "sellers can delete own ad_spaces" on ad_spaces as permissive for delete to authenticated
  using ((auth.uid() = seller_id));

create policy "sellers can insert own ad_spaces" on ad_spaces as permissive for insert to authenticated
  with check ((auth.uid() = seller_id));

create policy "sellers can update own ad_spaces" on ad_spaces as permissive for update to authenticated
  using ((auth.uid() = seller_id))
  with check ((auth.uid() = seller_id));

create policy "users can check their own admin status" on admins as permissive for select to authenticated
  using ((auth.uid() = user_id));

create policy "receiver can mark their messages read" on listing_messages as permissive for update to authenticated
  using ((auth.uid() = receiver_id))
  with check ((auth.uid() = receiver_id));

create policy "send to the listing seller, or reply as the seller" on listing_messages as permissive for insert to authenticated
  with check (((auth.uid() = sender_id) AND (sender_id <> receiver_id) AND (EXISTS ( SELECT 1
   FROM listings l
  WHERE ((l.id = listing_messages.listing_id) AND ((l.seller_id = listing_messages.receiver_id) OR ((l.seller_id = listing_messages.sender_id) AND (EXISTS ( SELECT 1
           FROM listing_messages m
          WHERE ((m.listing_id = listing_messages.listing_id) AND (m.sender_id = listing_messages.receiver_id) AND (m.receiver_id = listing_messages.sender_id)))))))))));

create policy "sender and receiver can view their messages" on listing_messages as permissive for select to authenticated
  using (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));

create policy "buyers and sellers can view proof changes of their orders" on listing_order_proof_changes as permissive for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM listing_orders o
  WHERE ((o.id = listing_order_proof_changes.order_id) AND ((o.buyer_id = auth.uid()) OR (o.seller_id = auth.uid()))))));

create policy "buyers and sellers can view their own orders" on listing_orders as permissive for select to authenticated
  using (((auth.uid() = buyer_id) OR (auth.uid() = seller_id)));

create policy "anyone can view active listings, sellers can view their own" on listings as permissive for select to anon, authenticated
  using (((status = 'active'::listing_status) OR (seller_id = auth.uid())));

create policy "sellers can delete own listings" on listings as permissive for delete to authenticated
  using ((auth.uid() = seller_id));

create policy "sellers can insert own listings" on listings as permissive for insert to authenticated
  with check ((auth.uid() = seller_id));

create policy "sellers can update own listings" on listings as permissive for update to authenticated
  using ((auth.uid() = seller_id))
  with check ((auth.uid() = seller_id));

create policy "anyone can view orders" on orders as permissive for select to anon, authenticated
  using (true);

create policy "buyers can create their own orders" on orders as permissive for insert to authenticated
  with check ((auth.uid() = buyer_id));

create policy "buyers can update their own confirmed orders" on orders as permissive for update to authenticated
  using (((auth.uid() = buyer_id) AND (status = 'confirmed'::order_status)))
  with check (((auth.uid() = buyer_id) AND (status = 'confirmed'::order_status)));

create policy "sellers can update their own orders" on orders as permissive for update to authenticated
  using ((auth.uid() = seller_id))
  with check ((auth.uid() = seller_id));

create policy "buyers and sellers can view their own payments" on payments as permissive for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM listing_orders o
  WHERE ((o.id = payments.order_id) AND ((o.buyer_id = auth.uid()) OR (o.seller_id = auth.uid()))))));

